from pathlib import Path
import base64,gzip

JAVA_GZ_B64=''

ui = Path('delivery-momentum/app/src/main/java/com/suhas/nsedeliverymomentum/MainActivity.java')
ui.write_bytes(gzip.decompress(base64.b64decode(JAVA_GZ_B64)))

build = Path('delivery-momentum/app/build.gradle')
s = build.read_text()
s = s.replace("versionCode 100", "versionCode 110")
s = s.replace("versionName '1.0.0'", "versionName '1.1.0'")
build.write_text(s)

styles=Path('delivery-momentum/app/src/main/res/values/styles.xml')
st=styles.read_text()
st=st.replace('#07131E','#050E18').replace('#24D6A1','#29D9A5')
styles.write_text(st)

text=ui.read_text()
for needle in ['NSE DELIVERY MOMENTUM','TOP CONTINUATION CANDIDATES','PAPER LEARNING','LIVE RANKING','BUY qualification looks for','Static IP OK']:
    assert needle in text, needle
assert "versionName '1.1.0'" in build.read_text()
assert "versionCode 110" in build.read_text()
print('Delivery Momentum v1.1.0 professional UI patch applied')
